45	// resolveFactsTarget resolves the repo, brain directory, and the branch facts
46	// are scoped to (the live git branch unless overridden). It is shared by the
47	// fact read/write commands.
48	func resolveFactsTarget(ctx context.Context, opts Options, target, branchOverride string) (repoDir, brainDir, branch string, err error) {
49		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
50		if err != nil {
51			return "", "", "", err
52		}
53		if !local {
54			return "", "", "", fmt.Errorf("memories require a local repository path: %s", target)
55		}
56		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
57		if err != nil {
58			return "", "", "", err
59		}
60		branch = strings.TrimSpace(branchOverride)
61		if branch == "" {
62			if current, gitErr := base.GitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
63				branch = strings.TrimSpace(current)
64			}
65		}
66		if branch == "" {
67			branch = distillDefaultBranch
68		}
69		return repoDir, storage.BrainDir, branch, nil
70	}
