138				globalIDs := map[string]bool{}
139				if globalFactsEnabled(noGlobal) {
140					globalFacts, globalErr := loadGlobalFacts(opts.Env)
141					if globalErr != nil {
142						// A damaged global store must not take recall down with it;
143						// the repository's own facts are the answer to most queries.
144						fmt.Fprintf(cmd.ErrOrStderr(), "warning: global memories unavailable: %v\n", globalErr)
145					} else {
146						allFacts, globalIDs = mergeGlobalFacts(allFacts, globalFacts)
147					}
148				}
149				var storeWarning string
150				manifest, manifestErr := bmanifest.Load(brainDir)
