257	func resolveRememberPaths(ctx context.Context, opts Options, rememberOpts rememberCommandOptions, repoDir, text string, taxonomy factstore.Taxonomy) ([]string, error) {
258		if strings.TrimSpace(rememberOpts.path) != "" {
259			paths := normalizeFactPaths(strings.Split(rememberOpts.path, ","))
260			if len(paths) == 0 {
261				return nil, fmt.Errorf("--path %q is not a valid taxonomy path (category.subcategory.type)", rememberOpts.path)
262			}
263			// Explicit paths must all sit under a known top-level category, exactly
264			// like agent-classified ones — otherwise --path can mint
265			// immediately-orphaned facts the rest of the system treats as invalid.
266			// Unlike the agent path (where unknown categories are dropped as noise),
267			// an explicit --path is deliberate, so any unknown category is a hard
268			// error rather than a silent drop that would hide a typo. New
269			// three-level paths under an existing category are still allowed.
270			var warnings []string
271			filtered := filterFactPathsByTaxonomy(paths, taxonomy, &warnings)
272			if len(filtered) != len(paths) {
273				return nil, fmt.Errorf("--path %q is not under a known taxonomy category (%s)", rememberOpts.path, strings.Join(factstore.SortedTaxonomyTopLevels(taxonomy), ", "))
274			}
275			return filtered, nil
276		}
277	
278		agent := rememberOpts.agent
279		if agent == "auto" {
280			agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
281		}
282		if agent == "none" || agent == "" {
283			return nil, fmt.Errorf("no agent available to classify; pass --path <category.subcategory.type>")
284		}
285		args, err := base.DistillAgentCommandArgs(agent, rememberOpts.agentCommand, classifyPrompt(taxonomy))
286		if err != nil {
287			return nil, err
288		}
289		args = base.InjectAgentModel(args, agent, rememberOpts.model)
290		run := rememberOpts.run
291		if run == nil {
292			run = defaultDistillAgentRunner(agent)
293		}
294		out, err := run(ctx, repoDir, args, []byte(text), defaultDistillTimeout)
295		if err != nil {
296			return nil, fmt.Errorf("classify memory: %w; pass --path to classify manually", err)
297		}
298		paths := parseClassifyOutput(out, taxonomy)
299		if len(paths) == 0 {
300			return nil, fmt.Errorf("agent did not return a valid taxonomy path; pass --path")
