314	// parseClassifyOutput extracts taxonomy paths from the classifier's response:
315	// the first line containing a valid path, comma- or whitespace-separated,
316	// filtered to known top-level categories and capped at two.
317	func parseClassifyOutput(output string, taxonomy factstore.Taxonomy) []string {
318		for _, line := range strings.Split(output, "\n") {
319			line = strings.TrimSpace(line)
320			if line == "" {
321				continue
322			}
323			fields := strings.FieldsFunc(line, func(r rune) bool { return r == ',' || r == ' ' || r == '\t' })
324			paths := normalizeFactPaths(fields)
325			var warnings []string
326			paths = filterFactPathsByTaxonomy(paths, taxonomy, &warnings)
327			if len(paths) > 0 {
328				return paths
329			}
330		}
331		return nil
332	}
