41	// A fact id is content-derived, so re-authoring a statement that was retracted
42	// lands on the retired record. The author asserted it is true again, so the
43	// record must go back to active — otherwise `remember` reports success while the
44	// fact stays unrecallable and the write is silently lost.
45	func TestRememberRevivesRetractedFact(t *testing.T) {
46		now := time.Date(2026, 6, 16, 12, 0, 0, 0, time.UTC)
47		opts, brainDir, branch := rememberReviveEnv(t, now)
48	
49		text := "The user prefers table-driven tests."
50		paths := normalizeFactPaths([]string{"preferences.coding.style"})
51		id := factRecordID(text, paths)
52		seed := []factRecord{{
53			ID: id, Paths: paths, Kind: factKindPreference, Text: text, Branch: branch,
54			Origin: factstore.OriginAuthored, Status: factStatusRetracted,
55			Provenance: []factAnchor{{SessionID: "s1"}},
56			CreatedAt:  now.Add(-time.Hour), UpdatedAt: now.Add(-time.Hour),
57		}}
58		if err := factstore.Write(brainDir, branch, seed); err != nil {
59			t.Fatal(err)
60		}
61	
62		printed := runRememberForTest(t, opts, text)
63	
64		got, err := factstore.Load(brainDir, branch)
65		if err != nil {
66			t.Fatal(err)
67		}
68		if len(got) != 1 {
69			t.Fatalf("want 1 fact, got %d: %+v", len(got), got)
70		}
71		if got[0].Status != factStatusActive {
72			t.Fatalf("re-authored fact is still %q after %q: the command reported success but the fact is not recallable", got[0].Status, printed)
73		}
74		if !got[0].UpdatedAt.Equal(now) {
75			t.Errorf("updated_at = %s, want the authoring time %s", got[0].UpdatedAt, now)
76		}
77		// Reviving must not discard the retired record's history.
78		if got[0].CreatedAt.Equal(now) {
79			t.Errorf("created_at was reset; the original record should be revived, not replaced")
80		}
81	}
