136	
137		text := "The service keeps durable facts in branch-scoped stores."
138		paths := normalizeFactPaths([]string{"preferences.coding.style"})
139		createdAt := now.Add(-time.Hour)
140		seed := factRecord{
141			ID: factRecordID(text, paths), Paths: paths, Kind: factKindPreference,
142			Text: text, Branch: branch, Origin: factstore.OriginDistilled,
143			Status: factStatusSuperseded, SupersededBy: "fact:newer",
