149			t.Fatal(err)
150		}
151	
152		cmd := NewRootCommand(opts)
153		out, err := execute(t, cmd, "remember", text,
154			"--path", "preferences.coding.style", "--agent", "none",
155			"--kind", factKindDecision, "--json")
156		if err != nil {
157			t.Fatalf("remember --json: %v\n%s", err, out)
158		}
159		var reported factRecord
160		if err := json.Unmarshal([]byte(out), &reported); err != nil {
161			t.Fatalf("decode remember JSON: %v\n%s", err, out)
162		}
163		stored, err := factstore.Load(brainDir, branch)
164		if err != nil {
165			t.Fatal(err)
166		}
167		if len(stored) != 1 {
168			t.Fatalf("stored facts = %+v, want one merged fact", stored)
169		}
170		if !reflect.DeepEqual(reported, stored[0]) {
171			t.Fatalf("remember JSON did not report the persisted fact:\nreported: %+v\nstored:   %+v", reported, stored[0])
172		}
173		if reported.Origin != factstore.OriginDistilled || !reported.CreatedAt.Equal(createdAt) {
174			t.Fatalf("original metadata was not retained: %+v", reported)
175		}
176		if reported.Status != factStatusActive || reported.SupersededBy != "" || reported.Kind != factKindDecision {
177			t.Fatalf("reactivation or explicit kind missing from JSON: %+v", reported)
178		}
179		if len(reported.Provenance) != 2 {
180			t.Fatalf("provenance = %+v, want retained and new anchors", reported.Provenance)
181		}
182	}
