38	func TestResolveRememberPathsExplicit(t *testing.T) {
39		now := time.Date(2026, 6, 5, 12, 0, 0, 0, time.UTC)
40		tax := factstore.DefaultTaxonomy(now)
41		// Explicit valid --path is used as-is (no agent call).
42		paths, err := resolveRememberPaths(context.Background(), Options{}, rememberCommandOptions{path: "preferences.coding.style"}, "/repo", "some fact", tax)
43		if err != nil || len(paths) != 1 || paths[0] != "preferences.coding.style" {
44			t.Fatalf("explicit path: %v err=%v", paths, err)
45		}
46		// Invalid explicit --path errors.
47		if _, err := resolveRememberPaths(context.Background(), Options{}, rememberCommandOptions{path: "not-a-path"}, "/repo", "f", tax); err == nil {
48			t.Fatalf("expected error for invalid --path")
49		}
50		// Syntactically valid but under an unknown top-level category is rejected,
51		// just like agent classification — no immediately-orphaned facts via --path.
52		if _, err := resolveRememberPaths(context.Background(), Options{}, rememberCommandOptions{path: "nonsense.foo.bar"}, "/repo", "f", tax); err == nil {
53			t.Fatalf("expected error for --path under unknown taxonomy category")
54		}
55		// A mix of a valid path and an unknown-category one rejects the whole --path
56		// rather than silently dropping the unknown (it's deliberate user input, so a
57		// typo must surface instead of storing under fewer paths than intended).
58		if _, err := resolveRememberPaths(context.Background(), Options{}, rememberCommandOptions{path: "preferences.coding.style,nonsense.foo.bar"}, "/repo", "f", tax); err == nil {
59			t.Fatalf("expected error when --path mixes valid and unknown-category paths")
60		}
61		// A new three-level path under a KNOWN top-level is still allowed (the
62		// taxonomy permits inventing paths under existing categories).
63		got, err := resolveRememberPaths(context.Background(), Options{}, rememberCommandOptions{path: "preferences.newarea.flavor"}, "/repo", "f", tax)
64		if err != nil || len(got) != 1 || got[0] != "preferences.newarea.flavor" {
65			t.Fatalf("new path under known category should be allowed: %v err=%v", got, err)
66		}
67	}
