// transcript chunk on stdin and returns stdout, bounded by a timeout and an
// output-size cap.
func defaultDistillAgentRunner(agent string) base.DistillAgentRunner {
	if agent == "ollama" {
		return execOllamaDistillAgent
	}
	if agent == "command" {
