func filterFactPathsByTaxonomy(paths []string, taxonomy factstore.Taxonomy, warnings *[]string) []string {
	tops := factstore.TaxonomyTopLevels(taxonomy)
	kept := paths[:0:0]
	for _, path := range paths {
