		}
		if !strings.Contains(req.Prompt, "The user prefers tabs.") {
			t.Fatalf("fact text not sent to ollama prompt: %q", req.Prompt)
		}
	default:
		t.Fatal("ollama server did not receive classification request")
	}
}

